package mz.bam.seeky.android;
import android.content.*;import android.database.*;import java.util.*;import org.json.*;

final class LibraryIndex {
    static void enqueue(Context c){try(TaskStore db=new TaskStore(c)){try(Cursor found=db.getReadableDatabase().rawQuery("SELECT id FROM jobs WHERE type='index' AND workspace=? AND state IN ('paused','queued','running') LIMIT 1",new String[]{TaskStore.workspace(c)})){if(found.moveToFirst())return;}String id=db.create("index","Preparar pesquisa nos livros",new JSONObject());if(c.getSharedPreferences("reading_tools",0).getBoolean("index_auto",false))TaskService.start(c,id);}catch(Exception e){AppDiagnostics.record(c,"index-queue",e);}}
    static void start(Context c){enqueue(c);try(TaskStore db=new TaskStore(c);Cursor found=db.getReadableDatabase().rawQuery("SELECT id FROM jobs WHERE type='index' AND workspace=? AND state IN ('paused','failed','queued') ORDER BY created DESC LIMIT 1",new String[]{TaskStore.workspace(c)})){if(found.moveToFirst())TaskService.start(c,found.getString(0));}}
    static void run(Context c,StudyStore.Row job,TaskStore work,TaskService.Control control)throws Exception{long revision=c.getSharedPreferences("reading_tools",0).getLong("index_revision",0);try(LibrarySearchStore index=new LibrarySearchStore(c);StudyStore books=new StudyStore(c)){index.scope();JSONObject payload=work.payload(job.s("id"));if(c.getSharedPreferences("reading_tools",0).getBoolean("index_dirty",false)&&!payload.optBoolean("started")){index.clear();payload.put("started",true).put("revision",revision);work.payload(job.s("id"),payload);}int offset=0,done=0;long total;String where=BookQuery.RAW_FORMATS+" AND id=(SELECT MIN(copy.id) FROM materials copy WHERE copy.hash=materials.hash AND copy.path=materials.path)";total=books.count("materials",where,null);
        while(true){control.check();List<StudyStore.Row> rows=books.page("materials",where,null,"id",20,offset);if(rows.isEmpty())break;for(StudyStore.Row book:rows){control.check();StudyStore.Row state=index.document(book.id());if(state!=null&&state.s("hash").equals(book.s("hash"))&&state.n("done")!=0){done++;continue;}control.progress("A indexar · "+book.s("title"),done,total);
            try(SpeechDocument source=new SpeechDocument(c,StudyFileProvider.uri(c,book.id()),book.s("name"),book.s("mime"),control::cancelled)){int count=source.count();if(state==null||!state.s("hash").equals(book.s("hash"))||state.n("parts")!=count){index.start(book.id(),book.s("hash"),count);state=index.document(book.id());}for(int part=(int)state.n("next_part");part<count;part++){control.check();String text=source.part(part);index.part(book.id(),part,text,source.partial||text.trim().isEmpty());control.progress(book.s("title")+" · "+(part+1)+" / "+count,done,total);}index.getWritableDatabase().update("documents",StudyStore.values("done",1),"material=?",new String[]{""+book.id()});}
            catch(java.io.InterruptedIOException e){throw e;}catch(Exception|OutOfMemoryError e){AppDiagnostics.record(c,"index-book",e);index.getWritableDatabase().insertWithOnConflict("documents",null,StudyStore.values("material",book.id(),"hash",book.s("hash"),"parts",0,"next_part",0,"done",1,"partial",1),android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}done++;}offset+=rows.size();}
        if(revision==c.getSharedPreferences("reading_tools",0).getLong("index_revision",0))c.getSharedPreferences("reading_tools",0).edit().putBoolean("index_dirty",false).apply();control.progress(done+" livros preparados para pesquisa.",done,total);
    }}
    static void dirty(Context c){android.content.SharedPreferences p=c.getSharedPreferences("reading_tools",0);p.edit().putBoolean("index_dirty",true).putLong("index_revision",System.currentTimeMillis()).apply();}
    private LibraryIndex(){}
}
